import java.util.*;

class Solution {
    public int[] cratePair(int[] weights, int capacity) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < weights.length; i++) {
            Integer j = seen.get(capacity - weights[i]);
            if (j != null) return new int[]{j, i};
            seen.put(weights[i], i);
        }
        return new int[0];
    }
}

